/* 학습 해설
 * SMB·세션과 공유 파일
 * 원격 서버의 공유 파일을 로컬 VFS처럼 다루려면 연결·인증·세션·캐시 일관성을 관리해야 합니다.
 * SMB 클라이언트는 서버와 프로토콜을 협상하고 세션 인증과 공유 연결을 마련합니다. 파일 open은 원격 handle과 연결되며 lease·캐시·재연결·DFS 경로가 동작에 영향을 줍니다. 로컬 write 완료와 원격 서버의 영구 저장 보장은 별도 규약입니다.
 * mount.cifs의 공유 경로·프로토콜·인증·캐시 옵션을 환경에 맞게 사용합니다. 암호를 공개 명령 기록에 넣지 않고 제공되는 자격 증명 관리 규약을 따릅니다. 서버·클라이언트·네트워크 오류를 구분합니다.
 */
int cifs_mount(struct cifs_sb_info *cifs_sb, struct smb3_fs_context *ctx)
{
	struct cifs_mount_ctx mnt_ctx = { .cifs_sb = cifs_sb, .fs_ctx = ctx, };
	int rc;

	rc = dfs_mount_share(&mnt_ctx);
	if (rc)
		goto error;
	if (!ctx->dfs_conn)
		goto out;

	/*
	 * After reconnecting to a different server, unique ids won't match anymore, so we disable
	 * serverino. This prevents dentry revalidation to think the dentry are stale (ESTALE).
	 */
	cifs_autodisable_serverino(cifs_sb);
	/*
	 * Force the use of prefix path to support failover on DFS paths that resolve to targets
	 * that have different prefix paths.
	 */
	cifs_sb->mnt_cifs_flags |= CIFS_MOUNT_USE_PREFIX_PATH;
	kfree(cifs_sb->prepath);
	cifs_sb->prepath = ctx->prepath;
	ctx->prepath = NULL;

